import { index, integer, jsonb, pgTable, real, text, timestamp, unique } from "drizzle-orm/pg-core";
import { idColumn, timestamps } from "./columns.js";
import { dealCandidateStatusEnum, estimateBasisEnum } from "./enums.js";
import { offers } from "./offer.js";

/** A candidate deal generated by the deal engine from a single offer observation. */
export const dealCandidates = pgTable(
  "deal_candidates",
  {
    id: idColumn(),
    offerId: text("offer_id")
      .notNull()
      .references(() => offers.id, { onDelete: "cascade" }),
    slug: text("slug").notNull(),

    dealScore: real("deal_score").notNull(),
    realDiscountPercentage: real("real_discount_percentage").notNull(),
    advertisedDiscountPercentage: real("advertised_discount_percentage"),

    historicalPriceScore: real("historical_price_score").notNull(),
    discountScore: real("discount_score").notNull(),
    commissionScore: real("commission_score").notNull(),
    sellerScore: real("seller_score").notNull(),
    popularityScore: real("popularity_score").notNull(),
    conversionScore: real("conversion_score").notNull(),
    freshnessScore: real("freshness_score").notNull(),
    confidenceScore: real("confidence_score").notNull(),

    estimatedEpcCents: integer("estimated_epc_cents").notNull().default(0),
    estimatedRevenuePer1000ImpressionsCents: integer("estimated_rpm_cents").notNull().default(0),
    estimateBasis: estimateBasisEnum("estimate_basis").notNull().default("heuristic"),

    status: dealCandidateStatusEnum("status").notNull().default("pending"),
    /** Human-readable signals explaining the score, e.g. LOWEST_PRICE_90D. */
    signals: jsonb("signals").$type<string[]>().notNull().default([]),
    reasoning: text("reasoning"),

    reviewedBy: text("reviewed_by"),
    reviewedAt: timestamp("reviewed_at", { withTimezone: true }),

    ...timestamps,
  },
  (table) => [
    unique("deal_candidates_slug_unique").on(table.slug),
    index("deal_candidates_offer_idx").on(table.offerId),
    index("deal_candidates_status_idx").on(table.status),
    index("deal_candidates_score_idx").on(table.dealScore),
  ],
);

export type DealCandidate = typeof dealCandidates.$inferSelect;
export type NewDealCandidate = typeof dealCandidates.$inferInsert;
